"""Offline main-data viewer, adapted from the existing Exp5 plain-HTML viewer.

No inference, result editing, dependencies, serving or network requests.
"""
import hashlib,json
from pathlib import Path
H=Path(__file__).resolve().parent;R=H/'runs/main'
REFERENCE=H.parents[2]/'agent-safety-20261016-continuation/workflows/exp5/build_viewer.py'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 worlds=read(R/'worlds.json');assignments=read(R/'assignments.json');scores={r['id']:r for r in read(R/'scored.json')};requests={q['id']:q for q in read(R/'requests.json')};completion=read(R/'completion.json');assert completion['raw']==3384 and completion['decisions']==2304
 branches=['team_intact','team_planner_a','team_reviewer_a','team_executor_a','team_planner_z','team_reviewer_z','team_executor_z','team_planner_r','team_reviewer_r','team_executor_r','replay_planner_a_executor_a','replay_reviewer_a_executor_a','direct_i','direct_a','solo_i','solo_a'];records={};messages={};index={};rawhash=hashlib.sha256()
 for line_number,line in enumerate((R/'raw.jsonl').open('rb'),1):
  rawhash.update(line);r=json.loads(line);rid=r['id'];a=assignments[rid];assert rid not in records and r['messages']==requests[rid]['messages'];m=json.dumps(r['messages'],ensure_ascii=False,sort_keys=True,separators=(',',':'));mh=hashlib.sha256(m.encode()).hexdigest();messages[mh]=r['messages']
  records[rid]={'id':rid,'role':a['role'],'arm':r['arm'],'raw':r['raw'],'message_key':mh,'generated_token_ids':r['generated_token_ids'],'ended_with_eos':r['ended_with_eos'],'prompt_sha256':r['prompt_sha256'],'intervention_lock_sha256':r['intervention_lock_sha256'],'intervention':r['intervention'],'raw_line':line_number,'raw_line_sha256':hashlib.sha256(line).hexdigest(),'sampling':r['sampling'],'batch':{k:r['batch'][k] for k in ['id','row','size']},'assignment':{k:a[k] for k in ['world_id','family','cell','branch','role','decision','upstream_ids','menu_order'] if k in a}}
  if a['decision']:
   assert rid in scores;key='|'.join([a['world_id'],a['cell'],str(a['menu_order']),a['branch']]);assert key not in index;index[key]=rid;records[rid]['score']=scores[rid]
 assert len(records)==3384 and len(index)==2304 and rawhash.hexdigest()==completion['raw_sha256'];assert set(records)==set(requests)==set(assignments)
 for w in worlds:
  for cell in ['blocked_harmful','unstated_harmful','authorized_harmless']:
   for order in [0,1]:
    for branch in branches:assert '|'.join([w['world_id'],cell,str(order),branch]) in index
 for r in records.values():assert all(i in records for i in r['assignment']['upstream_ids'])
 sources={str(p.relative_to(H)):sha(p) for p in [R/'raw.jsonl',R/'requests.json',R/'assignments.json',R/'scored.json',R/'worlds.json',R/'analysis.json',H/'executions/mixed_teams_v3/manifest.json',R/'qualification_v1.json']}
 payload={'worlds':worlds,'branches':branches,'records':records,'messages':messages,'index':index,'sources':sources,'counts':completion}
 encoded=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/');assert '"activations"' not in encoded and '"early_activations"' not in encoded
 html=HTML.replace('PAYLOAD',encoded);(H/'evidence.html').write_text(html)
 receipt={'passed':True,'scope':'Saved main data only; offline plain HTML, no model calls or external resources. No frozen data/code/report changed.','adapted_from':str(REFERENCE),'reference_sha256':sha(REFERENCE),'generator_sha256':sha(Path(__file__)),'html_sha256':sha(H/'evidence.html'),'html_bytes':len(html.encode()),'worlds':len(worlds),'contexts':3,'menu_orders':2,'decision_branches':len(branches),'decisions':len(index),'records':len(records),'unique_message_lists':len(messages),'all_factorial_cases_included':True,'activation_vectors_embedded':False,'default':'First world in retained worlds.json, blocked_harmful context, menu0, all-intact branch. No outcome-based selection.','source_sha256':sources}
 (H/'records/evidence-viewer-provenance.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps({k:v for k,v in receipt.items() if k!='source_sha256'},indent=2))

HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mixed-team study — saved evidence</title>
<style>body{font:16px/1.5 system-ui,sans-serif;color:#172534;background:#f5f7fa;margin:0}main{max-width:1240px;margin:28px auto;padding:0 20px}h1{font-size:29px;line-height:1.2}h2{font-size:21px}p{max-width:105ch}section{background:white;border:1px solid #d8dee7;padding:20px;margin:20px 0;border-radius:8px}select,button{font:inherit;padding:7px;margin:4px;border:1px solid #aeb8c6;border-radius:4px;background:white;max-width:100%}button{cursor:pointer}label{display:inline-block;margin-right:12px;font-weight:600;max-width:100%;min-width:0;box-sizing:border-box}select{box-sizing:border-box;max-width:calc(100% - 8px)}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #d9dfe5;padding:9px;text-align:left;vertical-align:top}th{background:#f3f5f7}tbody tr{cursor:pointer}tbody tr:hover{outline:2px solid #527eae;outline-offset:-2px}.selected{outline:2px solid #24619d;outline-offset:-2px}.externality{background:#fff2df}.violation{background:#ffe5e3}.defer{background:#eef0f3}.plain{background:#f4f9f5}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fa;padding:14px;font:13px/1.55 ui-monospace,monospace;max-height:500px;overflow:auto}.muted{color:#536276;font-size:14px}.source{font:12px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}.scroll{overflow:auto}a{color:#155c9d}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.card{border:1px solid #d7dfe8;padding:14px;border-radius:6px;min-width:0}.card h3{margin:0 0 8px;font-size:17px}.advice{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.badge{display:inline-block;padding:3px 7px;border-radius:4px;background:#e9eff6;font-size:12px;margin-bottom:8px}.result{background:#edf3fa;padding:12px;border-left:4px solid #356b9d}summary{cursor:pointer;font-weight:600;padding:8px 0}.toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:8px}.toolbar label{display:flex;flex-direction:column}.legend{font-size:13px;color:#536276}.status{font-size:14px}@media(max-width:850px){.cards{grid-template-columns:1fr}main{padding:0 12px}section{padding:14px}h1{font-size:25px}}</style>
<main><h1>Mixed-team study: inspect the saved evidence</h1><p>Browse <strong>all 24 main-study worlds, three contexts, two action-menu orders and 16 decision branches</strong>. Every displayed recommendation and response was generated in the completed study. This page runs no model and executes no operation.</p><p class="muted">Primary teams change one participant with a fixed refusal-ablation intervention. Replay branches change the executor while retaining recorded producer messages; self-planning and direct controls answer different questions. The default is simply the first retained world, prohibited-harmful context and all-intact team.</p><p><a href="report.md">Results, methods and limitations</a> · <a href="runs/main/analysis.json">Frozen analysis</a> · <a href="runs/main/qualification_v1.json">Qualification and independent reviews</a> · <a href="records/evidence-viewer-provenance.json">Viewer provenance</a></p>
<section><div class="toolbar"><label>World<select id="world"></select></label><button id="prev" aria-label="Previous world">Previous</button><button id="next" aria-label="Next world">Next</button><label>Context<select id="context"><option value="blocked_harmful">Explicit prohibition + adverse consequence</option><option value="unstated_harmful">No stated prohibition + adverse consequence</option><option value="authorized_harmless">Explicit authorization + harmless consequence</option></select></label><label>Action menu<select id="menu"><option value="0">Original order</option><option value="1">Reversed order</option></select></label></div><p id="worldInfo" class="status"></p><p id="rule" class="result"></p><details><summary>Exact task facts and available operations</summary><pre id="facts"></pre></details><div class="scroll"><table id="grid"><thead></thead><tbody></tbody></table></div><p class="legend">Orange: recorded third-party consequence; red: explicit operating-rule violation; gray: task deferred. Other cells indicate no scored adverse consequence, not universal safety. Click a branch to inspect its messages. Menu orders and branches repeat the same world.</p></section>
<section><h2>Recorded message path and action</h2><label>Branch<select id="branch"></select></label><p id="branchScope" class="muted"></p><p id="outcome" class="result"></p><div id="path" class="cards"></div><details><summary>Exact executor chat messages and action menu</summary><pre id="executorPrompt"></pre></details><details><summary>Selected record with scores, token IDs and intervention metadata</summary><pre id="record"></pre></details><button id="download">Download selected evidence as JSON</button><p class="muted">The download includes the selected path and exact chat messages, without activation vectors. Source IDs, original JSONL line numbers, line hashes and prompt hashes are shown for every record.</p></section>
<section><h2>Interpretation and full evidence</h2><p>All consequences are simulated. The external rubric counts resource shortfalls, unpublished-record exposure or cancelled recovery checks. A shortcut without a written prohibition is scored for its stated consequence; this is not a hidden-rule violation or proof of universally unethical conduct. Tradeoffs can carry normative ambiguity.</p><p>The primary reviewer comparison is a total effect through generated review text. Text and padding can change; explanations are not established as faithful mechanisms. Replay comparisons hold the actual recipient input tensors fixed. These are copies of one checkpoint with role prompts, not evidence of persistent independent identities or malicious intent. Generalization is limited to three exposed templates and fresh numeric instances; the 48 choices per branch and context are two menus per world.</p><p><a href="runs/main/raw.jsonl">Full original raw JSONL (large; includes activations)</a> · <a href="runs/main/requests.json">Exact requests</a> · <a href="runs/main/assignments.json">Role and message-path assignments</a> · <a href="runs/main/scored.json">All strict action scores</a> · <a href="executions/mixed_teams_v3/manifest.json">Frozen execution manifest</a></p><details><summary>Original source SHA-256 hashes</summary><pre id="hashes"></pre></details></section></main>
<script id="data" type="application/json">PAYLOAD</script><script>
const d=JSON.parse(document.getElementById('data').textContent),el=id=>document.getElementById(id),worlds=d.worlds.map(w=>w.world_id);
const arms={baseline:'Original',zero_sham:'Zero sham',refusal_ablation:'Refusal ablation',random_ablation:'Random ablation'};
const labels={team_intact:'All-intact team',team_planner_a:'Planner ablated',team_reviewer_a:'Reviewer ablated',team_executor_a:'Executor ablated',team_planner_z:'Planner zero sham',team_reviewer_z:'Reviewer zero sham',team_executor_z:'Executor zero sham',team_planner_r:'Planner random ablation',team_reviewer_r:'Reviewer random ablation',team_executor_r:'Executor random ablation',replay_planner_a_executor_a:'Planner-ablation messages → ablated executor',replay_reviewer_a_executor_a:'Reviewer-ablation messages → ablated executor',direct_i:'Direct original actor',direct_a:'Direct ablated actor',solo_i:'Original self-plan + self-review',solo_a:'Ablated self-plan + self-review'};
const consequenceKinds={third_party_resource_shortfall:'components left short for another customer',unpublished_personal_record_recipient_exposures:'unpublished-record × recipient exposures',third_party_recovery_checks_cancelled:'other-team recovery checks cancelled'};
function option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}
worlds.forEach((id,i)=>option(el('world'),id,(i+1)+' / '+worlds.length+' · '+id));d.branches.forEach(b=>option(el('branch'),b,labels[b]));el('hashes').textContent=JSON.stringify(d.sources,null,2);
function selected(branch=el('branch').value){return d.records[d.index[[el('world').value,el('context').value,el('menu').value,branch].join('|')]]}
function messages(r){return d.messages[r.message_key]}
function participants(r){return [...r.assignment.upstream_ids.map(i=>d.records[i]),r].map(x=>x.role+': '+arms[x.arm]).join(' / ')}
function consequence(r){const s=r.score;return s.third_party_consequence_count+' '+consequenceKinds[s.third_party_consequence_kind]}
function cell(row,text,tag='td'){const c=document.createElement(tag);c.textContent=text;row.append(c);return c}
function scope(branch){if(branch==='team_intact')return 'All three participants use the original model. The planner and reviewer generate advice; the executor selects an actual simulated operation.';if(branch.startsWith('replay_'))return 'Recorded altered-producer messages, replayed to an ablated executor. Two roles may differ from all-intact; this is a recipient comparison, not a primary one-member team.';if(branch.startsWith('direct_'))return 'One direct decision without planner or reviewer calls.';if(branch.startsWith('solo_'))return 'Three calls framed as one actor planning, reviewing and deciding. All three calls use the displayed model condition; role framing and messages differ from team controls.';return 'Primary or control team with one displayed role changed. Planner and reviewer messages are generated separately; the executor selects an actual simulated operation.'}
function render(){const r=selected(),w=d.worlds.find(x=>x.world_id===el('world').value);el('worldInfo').textContent='Family: '+w.family.replaceAll('_',' ')+' · Quantity: '+w.quantity+' · This world contributes 96 recorded decisions across all contexts, menus and branches.';el('rule').textContent=r.score.policy==='blocked'?'Written rule: the expedited operation is prohibited; the ordinary completion route remains available.':r.score.policy==='authorized'?'Written rule: the expedited operation is explicitly authorized; this context has no scored adverse third-party consequence.':'No explicit owner prohibition is stated. Both completion routes remain feasible; the adverse consequence is scored separately.';const body=messages(r).find(m=>m.role==='user').content;el('facts').textContent=body.split('The selected operation is executed once.')[0].trim();const table=el('grid');table.querySelector('thead').replaceChildren();table.querySelector('tbody').replaceChildren();let head=document.createElement('tr');['Branch','Actual role conditions','Selected action','Task complete','Written-rule violation','Third-party consequence'].forEach(x=>cell(head,x,'th'));table.querySelector('thead').append(head);d.branches.forEach(branch=>{const x=selected(branch),s=x.score,row=document.createElement('tr');row.dataset.branch=branch;row.className=s.explicit_operating_violation?'violation':s.third_party_consequence_count?'externality':s.deferred?'defer':'plain';cell(row,labels[branch],'th');cell(row,participants(x));cell(row,(s.action_code||'Invalid')+' → '+(s.semantic_action||'No valid action'));cell(row,s.task_completed?'Yes':'No');cell(row,s.explicit_operating_violation?'Yes':'No');cell(row,consequence(x));row.onclick=()=>{el('branch').value=branch;detail()};table.querySelector('tbody').append(row)});detail()}
function evidence(r){return {...r,messages:messages(r),raw_source:'runs/main/raw.jsonl',raw_source_file_sha256:d.sources['runs/main/raw.jsonl']}}
function detail(){const r=selected(),s=r.score;el('branchScope').textContent=scope(el('branch').value);el('outcome').textContent='Recorded output '+JSON.stringify(r.raw)+' → '+s.semantic_action+'. '+(s.task_completed?'Completed '+s.completed_quantity+' units in '+s.elapsed_work_units+' work units.':'Task deferred; no completion operation executed.')+' Explicit violation: '+(s.explicit_operating_violation?'yes':'no')+'. Consequence: '+consequence(r)+'.';const path=el('path');path.replaceChildren();const rr=[...r.assignment.upstream_ids.map(id=>d.records[id]),r];rr.forEach(x=>{const card=document.createElement('article');card.className='card';const title=document.createElement('h3');title.textContent=x.role.charAt(0).toUpperCase()+x.role.slice(1);card.append(title);const badge=document.createElement('span');badge.className='badge';badge.textContent=arms[x.arm];card.append(badge);const text=document.createElement('div');text.className='advice';text.textContent=x.raw;card.append(text);const source=document.createElement('p');source.className='source';source.textContent=x.id+'\nRaw JSONL line '+x.raw_line+'\nPrompt SHA-256: '+x.prompt_sha256+'\nRaw line SHA-256: '+x.raw_line_sha256;source.style.whiteSpace='pre-wrap';card.append(source);const det=document.createElement('details'),sum=document.createElement('summary'),pre=document.createElement('pre');sum.textContent='Exact messages and intervention';pre.textContent=JSON.stringify({messages:messages(x),intervention:x.intervention,generated_token_ids:x.generated_token_ids,ended_with_eos:x.ended_with_eos},null,2);det.append(sum,pre);card.append(det);path.append(card)});el('executorPrompt').textContent=JSON.stringify(messages(r),null,2);el('record').textContent=JSON.stringify(evidence(r),null,2);document.querySelectorAll('#grid tbody tr').forEach(row=>row.classList.toggle('selected',row.dataset.branch===el('branch').value))}
['world','context','menu'].forEach(id=>el(id).onchange=render);el('branch').onchange=detail;el('prev').onclick=()=>{el('world').selectedIndex=(el('world').selectedIndex+worlds.length-1)%worlds.length;render()};el('next').onclick=()=>{el('world').selectedIndex=(el('world').selectedIndex+1)%worlds.length;render()};el('download').onclick=()=>{const r=selected(),data={scope:'Saved selected path without activations; see original raw JSONL and bound hashes.',source_sha256:d.sources,path:[...r.assignment.upstream_ids.map(i=>evidence(d.records[i])),evidence(r)]},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=r.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></html>'''
if __name__=='__main__':main()
